1	const PROCESSING_FEE = 5;
2	
3	export type Item = {
4	  type: string;
5	  material?: string;
6	  enchantment?: number;
7	  cursed?: boolean;
8	};
9	
10	export type Step = {
11	  op: string;
12	  items: Item[];
13	};
14	
15	export type Scenario = {
16	  customer: { yearsWithMHPCO: number };
17	  steps: Step[];
18	};
19	
20	export type StepResult = {
21	  premium: number;
22	};
23	
24	export type ScenarioResults = {
25	  results: StepResult[];
26	};
27	
28	const ITEM_PREMIUMS: Record<string, number> = {
29	  sword: 110,
30	  amulet: 66,
31	};
32	
33	const itemPremium = (item: { type: string }): number => ITEM_PREMIUMS[item.type];
34	
35	const quote = (step: Step): StepResult => ({
36	  premium: step.items.reduce<number>(
37	    (total, item) => total + itemPremium(item),
38	    PROCESSING_FEE,
39	  ),
40	});
41	
42	export const runScenario = (scenario: Scenario): ScenarioResults => ({
43	  results: scenario.steps.map(quote),
44	});
45

1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: simplest cases -------------------------------------------------
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const scenario = {
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    };
11	
12	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
13	  });
14	  it("a single plain sword → premium 115 G (100 base + 10 first insurance + 5 fee)", () => {
15	    const scenario = {
16	      customer: { yearsWithMHPCO: 0 },
17	      steps: [
18	        {
19	          op: "quote",
20	          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
21	        },
22	      ],
23	    };
24	
25	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
26	  });
27	  it("a single plain amulet → premium 71 G (60 base + 6 first insurance + 5 fee)", () => {
28	    const scenario = {
29	      customer: { yearsWithMHPCO: 0 },
30	      steps: [
31	        {
32	          op: "quote",
33	          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
34	        },
35	      ],
36	    };
37	
38	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
39	  });
40	  it.todo("a single plain staff → premium 93 G (80 base + 8 first insurance + 5 fee)");
41	  it.todo("a single plain potion → premium 49 G (40 base + 4 first insurance + 5 fee)");
42	
43	  // --- Components and blocks -------------------------------------------------
44	  it.todo("a single rune → base premium 25 G");
45	  it.todo("2 runes → 50 G base premium");
46	  it.todo("3 runes → 60 G base premium (block applies)");
47	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
48	  it.todo("7 runes → 175 G base premium");
49	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
50	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
51	
52	  // --- Individual premium modifiers -----------------------------------------
53	  it.todo("cursed items add a 50 % risk surcharge to the item's base premium");
54	  it.todo("enchantment level 5 adds a 30 % high-enchantment surcharge");
55	  it.todo("enchantment level 4 adds no high-enchantment surcharge");
56	  it.todo("a cursed sword with exactly enchantment 5 gets both surcharges");
57	  it.todo("a customer with exactly 2 years with MHPCO gets the 20 % loyalty discount");
58	  it.todo("a customer with 1 year with MHPCO gets no loyalty discount");
59	  it.todo("the second contract of a scenario gets the 15 % follow-up discount");
60	
61	  // --- Modifier scope on multi-item policies --------------------------------
62	  it.todo(
63	    "cursed sword (100 G) + plain amulet (60 G) → curse adds 50 G on the item only → 210 G before further modifiers and fee",
64	  );
65	
66	  // --- Rounding --------------------------------------------------------------
67	  it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
68	  it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
69	
70	  // --- Claim: standard reimbursement ----------------------------------------
71	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
72	  it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G");
73	
74	  // --- Claim: special clauses ------------------------------------------------
75	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
76	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full, then deductible)");
77	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
78	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
79	
80	  // --- Claim: deductible per damage event -----------------------------------
81	  it.todo(
82	    "dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)",
83	  );
84	
85	  // --- Cap -------------------------------------------------------------------
86	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
87	  it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
88	  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G, cap 3500 G");
89	  it.todo("two swords → insurance sum 2000 G, cap 4000 G");
90	  it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
91	  it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");
92	
93	  // --- Multiple items of the same type --------------------------------------
94	  it.todo("two swords insured, both damaged → each damage entry gets its own deductible");
95	  it.todo("more damage entries of a type than insured → error (non-zero exit)");
96	
97	  // --- Error cases -----------------------------------------------------------
98	  it.todo("quote with an unknown item type (broomstick) → error");
99	  it.todo("claim referencing an item not part of the policy → error");
100	  it.todo("claim with a damage entry of an unknown item type → error");
101	  it.todo("claim with a damage entry amount -200 → error");
102	
103	  // --- Integration examples --------------------------------------------------
104	  it.todo("newcomer (0 years) with a cursed sword (steel, enchantment 3) → premium 165 G");
105	  it.todo("3-year customer's second quote, cursed sword enchantment 7 → premium 160 G");
106	
107	  // --- CLI -------------------------------------------------------------------
108	  it.todo("CLI reads the schema example from stdin and writes results to stdout");
109	  it.todo("CLI exits non-zero and writes to stderr on an unknown item type, with no results on stdout");
110	});
